-- 0074 (M3-S chat and player safety) — POSTCHECK. READ ONLY. Every row must be ok = true.
-- On staging: Staging database workflow, action m3_0074_postcheck.
with checks(item, ok, detail) as (
  select 'tables with row-level security on: player_blocks, reports, blocked_terms, account_suspensions', (select count(*) = 4 from pg_tables where schemaname = 'public' and tablename in ('player_blocks','reports','blocked_terms','account_suspensions') and rowsecurity), ''
  union all select 'reports, blocked_terms, account_suspensions: no direct access for signed-in or anonymous users', not has_table_privilege('authenticated', 'reports', 'select') and not has_table_privilege('authenticated', 'account_suspensions', 'select') and not has_table_privilege('authenticated', 'blocked_terms', 'select') and not has_table_privilege('anon', 'reports', 'select'), ''
  union all select 'player_blocks: no direct writes', not has_table_privilege('authenticated', 'player_blocks', 'insert') and not has_table_privilege('authenticated', 'player_blocks', 'delete'), ''
  union all select 'blocked_terms is empty (the list needs approval)', (select count(*) = 0 from blocked_terms), (select count(*)::text from blocked_terms)
  union all select 'join guard trigger on match_players: before insert, enabled', exists (select 1 from pg_trigger where tgname = 'match_players_block_guard' and tgenabled = 'O'), ''
  union all select 'chat read policy hides a blocked sender from the blocker', (select qual from pg_policies where tablename = 'match_messages' and policyname = 'match_messages: members read') like '%player_blocks%', ''
  union all select 'admin functions: callable by signed-in users (each checks is_admin), never anonymous', has_function_privilege('authenticated', 'admin_reports(text)', 'execute') and not has_function_privilege('anon', 'admin_reports(text)', 'execute') and not has_function_privilege('anon', 'admin_suspend(uuid,text)', 'execute'), ''
  union all select 'internal helpers not callable through the API', not has_function_privilege('authenticated', 'assert_active()', 'execute') and not has_function_privilege('authenticated', 'players_blocked(uuid,uuid)', 'execute') and not has_function_privilege('authenticated', 'message_has_blocked_term(text)', 'execute'), ''
  union all select 'post_match: the 0074 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '65b3a0d219612205d3ceacb6d2f55292' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select 'join_match: the 0074 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '96298454878cbed0b1623b47f6a738bd' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), 'missing')
  union all select 'decide_join: the 0074 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'f6a5fe93357165780e253f2893d7f5a0' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), 'missing')
  union all select 'update_match: the 0074 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'e43d7f4d834289258e4202392028b8d2' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), 'missing')
  union all select 'set_match_status: the 0074 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'ecbe1c55f918b4e81608afa7fd7de12d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), 'missing')
