  union all select 'unblock_player: the 0074 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '7949f194640e87edc0c172e67ac6449e' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'unblock_player'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'unblock_player'), 'missing')
